head.script:
scwin.onpageload = function() {
	scwin.windowIdx = 1;
};
scwin.onpageunload = function() {};
scwin.btn_trigger1_onclick = function(e) {
    main_ctn.createWindow("window" + scwin.windowIdx, null, "windowContainer_createSubmission_WESD-137_(WSQ-4316)_sub.xml", "window" + scwin.windowIdx, scwin.windowIdx, "existWindow", null, null, null, null, "wframe");
    scwin.windowIdx++;
};
scwin.checkVal = function() {
    return WebSquare.WebSquaredoc.models[0].submissions.length == 0;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('main_ctn_closeAll').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
